using System;using System.Drawing;using System.Drawing.Drawing2D;
namespace IslandIntegrated {
 public sealed class StatusSignal {
  public string Kind,Text;public Color Color;
  public static StatusSignal From(LegacySnapshot s){var now=DateTimeOffset.UtcNow;return FromEvidence(s,now,WebsiteLatency.Signal(now));}
  public static StatusSignal FromEvidence(LegacySnapshot s,DateTimeOffset now,string measurement){if(s==null||!s.IsFresh(now))return Make("unknown","网络状态数据不可用",Color.FromArgb(165,181,199));if(s.NetworkKnown&&!s.NetworkAvailable)return Make("error","系统报告网络未连接",Color.FromArgb(255,130,130));if(measurement=="slow")return Make("warning","网站平均耗时超过 300 ms",Color.FromArgb(255,205,90));if(measurement=="unreachable")return Make("warning","测试站点均未响应",Color.FromArgb(255,205,90));if(measurement=="normal")return Make("normal","网站平均耗时不超过 300 ms",Color.FromArgb(110,235,160));return Make("unknown","尚无新鲜的网站测速结果",Color.FromArgb(165,181,199));}
  static StatusSignal Make(string kind,string text,Color color){return new StatusSignal{Kind=kind,Text=text,Color=color};}
  public static double Pulse(string kind,double seconds,bool reduced){if(reduced||(kind!="warning"&&kind!="error"))return 1;double period=kind=="warning"?4.0:6.0;return .75+.25*Math.Sin(seconds*2*Math.PI/period);}
  public static bool ReduceMotion;
  public void Paint(Graphics g,int width,int height){float h=height<232?48:30,y=height<232?(height-h)/2f:20;int alpha=(int)(255*Pulse(Kind,DateTime.UtcNow.TimeOfDay.TotalSeconds,ReduceMotion));using(var halo=new GraphicsPath()){halo.AddEllipse(5,y-6,18,h+12);using(var glow=new PathGradientBrush(halo)){glow.CenterColor=System.Drawing.Color.FromArgb(48,Color);glow.SurroundColors=new[]{System.Drawing.Color.FromArgb(0,Color)};g.FillPath(glow,halo);}}using(var r=GlassSurface.Path(new RectangleF(12,y,4,h),2))using(var b=new SolidBrush(System.Drawing.Color.FromArgb(alpha,Color)))g.FillPath(b,r);using(var p=new Pen(Color,1.25f)){p.StartCap=p.EndCap=LineCap.Round;float x=width-(height<232?105:119),cy=24;if(Kind=="error"){g.DrawLine(p,x,cy-3,x+6,cy+3);g.DrawLine(p,x+6,cy-3,x,cy+3);}else if(Kind=="warning"){g.DrawLine(p,x+3,cy-4,x+3,cy);g.DrawEllipse(p,x+2.6f,cy+2,1,1);}else if(Kind=="normal"){g.DrawLines(p,new[]{new PointF(x,cy),new PointF(x+2,cy+2),new PointF(x+6,cy-3)});}else g.DrawLine(p,x,cy,x+6,cy);}}
 }
 public static class StatusMaterial {
  static void Glow(Graphics g,RectangleF r,Color c){using(var p=new GraphicsPath()){p.AddEllipse(r);using(var b=new PathGradientBrush(p)){b.CenterColor=c;b.SurroundColors=new[]{Color.FromArgb(0,c)};g.FillPath(b,p);}}}
  // Original source lines1026–1075: tinted base,64-alpha crown sheen,
  // green/coral/lower-blue caustics and a15-alpha diagonal reflection.
  // These are native GDI material layers, not desktop capture or optical blur.
  public static void Paint(Graphics g,RectangleF r,float radius,bool original){var saved=g.Save();using(var path=GlassSurface.Path(r,radius)){g.SmoothingMode=SmoothingMode.AntiAlias;using(var b=new LinearGradientBrush(r,original?Color.FromArgb(224,46,51,66):Color.FromArgb(188,Palette.Top),original?Color.FromArgb(240,14,16,23):Color.FromArgb(204,Palette.Base),LinearGradientMode.Vertical))g.FillPath(b,path);}g.Restore(saved);Finish(g,r,radius,original);}
  public static void Finish(Graphics g,RectangleF r,float radius,bool original){var saved=g.Save();using(var path=GlassSurface.Path(r,radius)){g.SmoothingMode=SmoothingMode.AntiAlias;g.SetClip(path,CombineMode.Intersect);using(var sheen=new LinearGradientBrush(new PointF(0,r.Top-4),new PointF(0,r.Top+156),Color.FromArgb(original?64:64,255,255,255),Color.Transparent)){sheen.WrapMode=WrapMode.TileFlipXY;g.FillRectangle(sheen,r.Left,r.Top-4,r.Width,160);}Glow(g,new RectangleF(r.Left+r.Width*.72f-90,r.Top-60,200,180),original?Color.FromArgb(30,70,230,160):Color.FromArgb(52,Palette.Face));Glow(g,new RectangleF(r.Left+r.Width*.04f-40,r.Top+r.Height*.3f,170,190),Color.FromArgb(30,240,150,120));if(r.Height>180)Glow(g,new RectangleF(r.Left+r.Width*.5f-90,r.Bottom-40,180,150),Color.FromArgb(original?14:26,110,160,255));var band=g.Save();g.TranslateTransform(r.Left+r.Width*.4f,r.Top+r.Height*.3f);g.RotateTransform(-24);using(var b=new LinearGradientBrush(new PointF(-150,0),new PointF(150,0),Color.Transparent,Color.Transparent)){b.InterpolationColors=new ColorBlend(3){Colors=new[]{Color.Transparent,Color.FromArgb(15,255,255,255),Color.Transparent},Positions=new[]{0f,.5f,1f}};float extent=original?260:r.Height+r.Width+400;g.FillRectangle(b,-150,-extent,300,extent*2);}g.Restore(band);using(var edge=new LinearGradientBrush(r,Color.FromArgb(168,239,251,255),Color.FromArgb(46,191,224,242),LinearGradientMode.Vertical))using(var pen=new Pen(edge,1.05f))g.DrawPath(pen,path);}g.Restore(saved);}
 }
 public static class WeatherMaterial {
  public static Color Text {get{return System.Windows.Forms.SystemInformation.HighContrast?SystemColors.WindowText:Color.FromArgb(249,252,255);}}public static Color Secondary {get{return System.Windows.Forms.SystemInformation.HighContrast?SystemColors.WindowText:Color.FromArgb(222,234,244);}}
  public static WeatherKind VisualKind(WeatherKind kind,string description){if(kind==WeatherKind.Cloud&&!String.IsNullOrWhiteSpace(description)&&description.IndexOf("雾",StringComparison.Ordinal)>=0)return WeatherKind.Fog;return kind;}
  public static Bitmap Create(Size size,WeatherKind kind){return Create(size,kind,null);}
  public static Bitmap Create(Size size,WeatherKind kind,string description){return GlassSurface.CardBackground(size);}

 }
 public static class WeatherCredit {
  public static System.Windows.Forms.ContextMenuStrip Menu(Func<WeatherSnapshot> current){var menu=new System.Windows.Forms.ContextMenuStrip();menu.Items.Add("\u5929\u6c14\u6570\u636e\u4e0e\u66f4\u65b0\u65f6\u95f4",null,(sender,args)=>{var s=current();string stamp=s.ObservedAt.HasValue?s.ObservedAt.Value.ToOffset(TimeSpan.FromSeconds(s.OffsetSeconds)).ToString("yyyy-MM-dd HH:mm zzz"):"\u5c1a\u65e0\u6570\u636e";System.Windows.Forms.MessageBox.Show("Open-Meteo\nhttps://open-meteo.com/\nCC BY 4.0 · https://creativecommons.org/licenses/by/4.0/\n\n\u66f4\u65b0\uff1a"+stamp+"\n\u72b6\u6001\uff1a"+s.EffectiveState(DateTimeOffset.UtcNow),"\u5173\u4e8e\u5929\u6c14\u6570\u636e");});return menu;}
 }
}
